import{_ as t}from"./chunks/log-bb-player.pc.en.i6OweW45.js";import{_ as o,o as s,c as n,a5 as r}from"./chunks/framework.BMR-TWOq.js";const a="/RBQ/nightly/images/app/log-rt.pc.en.png",i="/RBQ/nightly/images/app/log-sys.pc.en.png",w=JSON.parse('{"title":"Logs","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/logs.md","filePath":"manual/gui/logs.md","lastUpdated":1794894003000}'),l={name:"manual/gui/logs.md"};function h(g,e,d,c,p,m){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h1><p>Open the <strong>Black Box</strong> screen with the <code>Black Box</code> tile on the hub. The tile works without a robot too: <strong>System Log</strong> and <strong>Black Box</strong> load once the robot is connected, and until then <strong>Black Box</strong> opens on <strong>Library</strong> — the sessions you saved on this device. A red <strong>ERROR</strong> / <strong>FATAL</strong> toast or a row in the alert badge popover on the control home also opens it (see <a href="#real-time">Real Time Log</a>). Every user can open it. It has three tabs and opens on <strong>Black Box</strong>; the filter bar below is on <strong>Real Time Log</strong> and <strong>System Log</strong>. A Black Box session&#39;s log is filtered in the <strong>SYSTEM LOG</strong> pane of the replay view.</p><p><img src="'+a+'" alt="Real Time Log tab"></p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Content</th></tr></thead><tbody><tr><td><strong>Black Box</strong></td><td>Recordings saved when the robot fell, when control was turned off, when the joystick signal stopped while you were driving, or when you pressed <strong>Save now</strong> — 30 s of motion data plus the system log of that moment</td></tr><tr><td><strong>Real Time Log</strong></td><td>Messages streamed from the robot while the app is connected</td></tr><tr><td><strong>System Log</strong></td><td>Log files stored on the robot, one per day</td></tr></tbody></table><p>A dot next to the tabs shows the log link: <strong>Connected</strong>, <strong>Connecting</strong>, or <strong>Disconnected</strong>.</p><p><strong>Save</strong> and <strong>Save zip</strong> keep going if you move to another screen. Meanwhile a banner at the top shows the save, and if it ends while you are elsewhere, the banner shows the result once. On the phone and tablet apps the share window then does not open over the other screen: the banner adds <strong>tap to share</strong>, and tapping it brings you back to <strong>Black Box</strong>, where <strong>Share</strong> sends the file.</p><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><ul><li><strong>LEVEL</strong> chips — <strong>TRACE</strong>, <strong>DEBUG</strong>, <strong>INFO</strong>, <strong>SUCCESS</strong>, <strong>WARNING</strong>, <strong>ERROR</strong>, <strong>FATAL</strong>. Tap a chip to hide that level; tap again to show it. <strong>TRACE</strong> and <strong>DEBUG</strong> start hidden.</li><li><strong>PROC</strong> chips — one per process in the current source, in alphabetical order, each in its own color. Tap to hide or show.</li><li><strong>Search</strong> — filters on the message text or the process name.</li><li>The count at the right of the action bar reads <em>shown / total</em> <strong>lines</strong>. Very long files show only the latest 2,500 lines, with a notice at the top.</li></ul><h2 id="real-time" tabindex="-1">Real Time Log <a class="header-anchor" href="#real-time" aria-label="Permalink to &quot;Real Time Log {#real-time}&quot;">​</a></h2><ul><li><strong>Auto-scroll</strong> — keeps the newest line at the bottom. Scrolling up to read older lines turns it off and holds the list still; turn it back on to return to the bottom.</li><li><strong>Save</strong> — saves the currently filtered lines to your device.</li><li>Tapping a red <strong>ERROR</strong> / <strong>FATAL</strong> toast, or a row in the alert badge popover, opens this tab with that line highlighted so you can see what happened around it.</li><li>On the control home, toasts never cover the view menu, the <code>Spectating</code> pill, the SLAM map status or the gauges at the bottom. When a small screen has no room, only the newest toasts that fit are shown, but the newest one always shows: the SLAM map status and then the <code>Spectating</code> pill step aside for it until it fades. The alert badge still counts every line.</li></ul><h2 id="system-log" tabindex="-1">System Log <a class="header-anchor" href="#system-log" aria-label="Permalink to &quot;System Log {#system-log}&quot;">​</a></h2><p><img src="'+i+'" alt="System Log tab"></p><ol><li><strong>Fetch</strong> — loads the list of days from the robot (this runs by itself the first time you open the tab, and the newest day is selected).</li><li><strong>DATE</strong> — choose a day; the file is loaded and shown with the filters above.</li><li><strong>Timeline replay</strong> — plays the day&#39;s log as a timeline: play / pause, step to the previous or next line, a position slider, and a speed button that cycles through 0.25× … 16×, 60×, and 300× (the fast speeds skip long quiet stretches). Tapping a line jumps to that moment. <strong>Close</strong> returns to the list.</li><li><strong>Save</strong> — saves the raw log file of the selected day to your device.</li></ol><h2 id="black-box" tabindex="-1">Black Box <a class="header-anchor" href="#black-box" aria-label="Permalink to &quot;Black Box {#black-box}&quot;">​</a></h2><p><img src="'+t+'" alt="Black Box replay"></p><ol><li><strong>Robot</strong> / <strong>Library</strong> — where the sessions come from: the connected robot, or the sessions kept on this device, filed by robot serial number. With no robot connected the tab opens on <strong>Library</strong>, so you can replay without the robot.</li><li><strong>Fetch</strong> — loads the list of sessions (this runs by itself the first time you open the tab).</li><li><strong>DATE</strong> and <strong>SESSION</strong> — choose a recording; the newest session of the day is opened first and the replay view is shown. In <strong>Library</strong>, <strong>S/N</strong> picks the robot first, and <strong>Delete</strong> removes the selected session from this device (the robot keeps its own copy).</li><li><strong>Save now</strong> — asks the robot to record a black-box session right now — use it right after something looked wrong.</li><li><strong>Open zip</strong> — replays a session zip saved earlier on this device, without the robot, and keeps it in <strong>Library</strong> under the serial number found in the zip — the one the robot wrote into <code>meta.json</code>, else the one in the file name; with neither it goes under <strong>No S/N</strong>. On the <strong>Robot</strong> source, <strong>Close — to robot session</strong> returns to the robot&#39;s list.</li><li><strong>Save zip</strong> — saves the selected session (data and log) to your device and keeps a copy in <strong>Library</strong> under the robot&#39;s serial number. The file name carries the serial number too (<code>blackbox-&lt;serial&gt;-20260911_08_32_18.zip</code>): sessions recorded by older robot software do not say which robot they came from, so for those the file name is what tells the saved zips apart.</li></ol><h3 id="replay-view" tabindex="-1">Replay view <a class="header-anchor" href="#replay-view" aria-label="Permalink to &quot;Replay view&quot;">​</a></h3><ul><li>The header reads <strong>Black Box Playback</strong> with the duration and <strong>which robot the session came from</strong> (its serial number). The app takes it from what the robot wrote when it saved the session, then the zip&#39;s file name, then the connected robot. With none of the three it reads <strong>Robot unknown</strong>; sessions saved before this existed carry no stamp of their own, so they read unknown or show the connected robot.</li><li>View buttons: <strong>Split</strong> (3D pose + log), <strong>Quad</strong> (3D, status, camera, and log panes), <strong>3D</strong>, <strong>Data</strong>, <strong>Video</strong> (the event clip on its own), <strong>Logs</strong>, <strong>Analysis</strong> (graphs). The player opens in <strong>Quad</strong>.</li><li>On a phone in landscape, the tabs and the <strong>DATE</strong> / <strong>SESSION</strong> row fold away during replay. Tap <strong>Session</strong> to show them.</li><li>The <strong>Status</strong> pane (bottom-left of Quad) shows, from the left, an attitude dial (roll and pitch, with R, P and Y values beside it), a gamepad diagram, and two rows of cards. Anything abnormal turns red. Tap the dial, the gamepad or a card to switch to <strong>Data</strong> with that value&#39;s section unfolded. <ul><li>The gamepad diagram shows where both sticks point and which buttons are held (shoulders, D-pad, ABXY, stick press) at that moment. Buttons it does not draw, and LT and RT, appear by name on the <strong>BTN</strong> card.</li><li>Cards: gait (GAIT — the name the robot uses, for example <code>RL_WALK_VISION</code>), fall (FALL), batteries (BAT L/R V), command (CMD VX), buttons (BTN), CPU temperature (CPU TEMP), CPU throttling (THROTTLE), joints with a motor stall (STALL) or overcurrent (OVERCUR), and deadline misses (MISS).</li><li>When the pane is narrow the R, P and Y values are left out first, then the cards go to three rows.</li></ul></li><li>The <strong>camera</strong> pane plays the <strong>event clips</strong> (front and rear) for that moment, and playback follows the data timeline. If the robot is still encoding them, the clips may not have arrived yet — try again in a moment. An exported zip carries the clips too, so it replays without the robot.</li><li><strong>Ref</strong> (top-right of the 3D pane) overlays the reference pose as a translucent ghost so you can compare commanded and measured joints. It starts off.</li><li>The <strong>Data</strong> pane shows <strong>every recorded channel</strong> of the current frame. The <em>miss</em> chip counts control deadline misses; the number beside it is how many channels this recording holds. <ul><li>Channels are grouped into sections you can fold and unfold. <strong>JOINT</strong> starts unfolded.</li><li>Groups that are numbered or named — joints, wheels, ports — are drawn as tables: <strong>one row is one joint</strong>, carrying its angle, velocity, torque, motor current, temperatures, errors and CAN receive rate side by side. Wide tables scroll sideways inside the pane.</li><li>Type a channel name in the box at the top to keep only the groups that match (for example <code>motor.cur</code>, <code>can</code>).</li><li>Angles read in degrees; everything else keeps the unit it was recorded in. Error and miss channels turn red when they are not zero.</li><li>Channels the robot does not record get no row at all.</li></ul></li><li>The <strong>Analysis</strong> view plots the whole session over time. <ul><li>Pick what to plot with the buttons on top: <strong>Overview</strong>, <strong>Torque</strong> (measured solid, reference dashed), <strong>Current</strong> (±15 A limit dashed), <strong>Joint position</strong>, <strong>Temp</strong>, <strong>IMU</strong>, <strong>CPU · System</strong>, <strong>Power</strong>, <strong>Custom</strong>. It opens on <strong>Overview</strong>.</li><li><strong>Overview</strong> puts attitude (RPY), gyro, commanded velocity, knee torque and current for all four legs, battery voltage, CPU temperature and deadline misses on one screen.</li><li>Torque, current, joint position and temperature start on <strong>All legs</strong>, showing the four legs on one screen (one row per leg, one column per joint R, P, K). Pick FL, FR, HL or HR to see one leg larger.</li><li>Graphs sit in as many columns as the width allows and shrink in height to fit one screen.</li><li>Each graph&#39;s legend shows the value at the replay position, so switching to another set still reads the same moment.</li><li>The set, leg and span you picked stay when you switch to another view and back.</li><li>The 3D pane sits beside the graphs (above them on a narrow screen) and shows the pose at the replay position, with <strong>Ref</strong> as in the other views.</li><li><strong>Custom</strong> plots up to six channels you find by name. Tap a picked channel to drop it.</li><li><strong>All</strong> · <strong>20s</strong> · <strong>5s</strong> · <strong>1s</strong> set the visible span. A narrower span keeps the replay position in the middle.</li><li>The blue vertical line is the replay position. Tap or drag on a graph to seek there.</li></ul></li><li>The bottom bar has previous / next frame, play / pause, a slider, the wall-clock time and frame counter, and a speed button cycling 0.25× … 16×.</li><li>The <strong>SYSTEM LOG</strong> pane scrolls in step with the replay position. Tap a line to seek there. The <strong>Search</strong> box at its top keeps the lines whose message or process name match, and the level chips hide that level (<strong>TRACE</strong> and <strong>DEBUG</strong> start hidden). A <strong>Time sync uncertain</strong> notice appears when the recording lacks timing metadata or the clocks differ.</li></ul><h2 id="find-errors" tabindex="-1">Skimming for errors <a class="header-anchor" href="#find-errors" aria-label="Permalink to &quot;Skimming for errors {#find-errors}&quot;">​</a></h2><p>Here is how to pinpoint the moment something went wrong in a whole day of logs, in seconds.</p><ol><li>In the <strong>LEVEL</strong> chips, press <code>INFO</code>, <code>SUCCESS</code>, and <code>WARNING</code> to <strong>hide</strong> them (<code>TRACE</code> and <code>DEBUG</code> start hidden). Only <code>ERROR</code> and <code>FATAL</code> remain.</li><li>Press the <strong>next line</strong> button in the timeline replay repeatedly — it steps only between the lines that are still shown, so it jumps from error to error.</li><li><strong>Write down the timestamp</strong> where you stop (for example <code>19:30:48.855</code>).</li><li>If you need the surrounding context, turn <code>WARNING</code> or the relevant <strong>PROC</strong> chips back on there.</li></ol><p>When you do not know which process started the problem, skim with every <strong>PROC</strong> chip on, then narrow to that one process once the range is clear.</p><h2 id="for-support" tabindex="-1">What to send when you contact us <a class="header-anchor" href="#for-support" aria-label="Permalink to &quot;What to send when you contact us {#for-support}&quot;">​</a></h2><p>These three together make the cause far quicker to find.</p><ol><li><strong>The error messages</strong> — the <code>ERROR</code> and <code>FATAL</code> list you found with <a href="#find-errors">Skimming for errors</a>. Use <strong>Save</strong> to write a file, or capture the screen.</li><li><strong>The timestamp</strong> — note when the message appeared.</li><li><strong>Video from around that time</strong> — nothing settles it faster than seeing what the robot was doing.</li></ol><p>The software version and the steps to reproduce help too. For a momentary problem such as a fall or an emergency stop, include the <strong>Black Box session</strong> as well, saved with <strong>Save zip</strong>.</p><p><strong>→ <a href="/RBQ/nightly/manual/support/">Support</a></strong></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>The battery, joint, and sensor status behind many log messages is on the <a href="/RBQ/nightly/manual/gui/dashboard.html">Dashboard</a>.</li></ul>',30)])])}const f=o(l,[["render",h]]);export{w as __pageData,f as default};
